CREATE COLUMN TABLE "TEST_AP"."AMGP" ("AbsEntry" INTEGER CS_INT NOT NULL , "MatGrp" NVARCHAR(3) NOT NULL , "Descrip" NVARCHAR(70), "LogInstanc" INTEGER CS_INT NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "AMGP_CODE" ON "TEST_AP"."AMGP" ( "MatGrp" ASC, "LogInstanc" ASC )